<script setup lang="ts">
const { site, phoneDisplay } = useSite()
usePageSeo({ title: 'الشروط والأحكام', description: 'شروط وأحكام استخدام موقع مكة للسياحة وحجز برامج العمرة والحج: الحجز والتأكيد والأسعار والدفع والمستندات والتأشيرات والإلغاء والمسؤولية.', breadcrumbs: [{ name: 'الشروط والأحكام', path: '/terms' }] })
const highlights = [
  'إرسال طلب الحجز من الموقع ليس حجزًا مؤكدًا؛ يصبح مؤكدًا بعد تأكيد فريقنا وسداد المبالغ المتفق عليها.',
  'السعر النهائي هو المؤكد كتابيًا عند الحجز، وما يشمله البرنامج وما لا يشمله مذكور في صفحته.',
  'قرار منح التأشيرة للجهات الرسمية، وعلى المسافر تقديم مستندات صحيحة وسارية في الموعد.',
  'شروط الإلغاء والاسترداد مفصلة في صفحة «سياسة الإلغاء والاسترداد».',
]
const sections = computed(() => [
  { h: 'القبول والتعريفات', p: [`تحكم هذه الشروط استخدامك لموقع «${site.value.name}» وطلبك لأي برنامج أو خدمة عبره. باستخدام الموقع أو إرسال طلب حجز فإنك توافق على هذه الشروط وعلى سياسة الخصوصية وسياسة الإلغاء والاسترداد، وهي جميعًا جزء لا يتجزأ من الاتفاق بينك وبين الشركة.`, '«الشركة» تعني مكة للسياحة، و«العميل» أو «المسافر» هو من يطلب الخدمة أو يسافر بها، و«البرنامج» هو الرحلة المعروضة بمدتها وإقامتها ومواعيدها وأسعارها.'] },
  { h: 'طبيعة الموقع والخدمات', p: ['يعرض الموقع برامج العمرة والحج والسياحة الدينية ومعلومات عنها لتمكين العميل من طلب الحجز. تُقدَّم الخدمات الفعلية عبر الشركة وشركائها من شركات الطيران والفنادق ومقدمي النقل والإرشاد. المحتوى المنشور للتعريف العام، وقد تختلف تفاصيل بعض البرامج من موعد لآخر، والمعتمد هو ما يُؤكد للعميل كتابيًا عند الحجز.'] },
  { h: 'الأهلية وصحة البيانات', ul: [
    'يجب أن يكون العميل بالغًا وكامل الأهلية القانونية، أو أن يتصرف بصفته ولي أمر المسافر القاصر أو نائبه.',
    'يلتزم العميل بتقديم بيانات صحيحة ودقيقة وكاملة، خاصة الاسم كما في الجواز وأرقام التواصل.',
    'تتحمل أنت مسؤولية أي تأخير أو رفض أو رسوم تنتج عن بيانات غير صحيحة قدمتها.',
  ] },
  { h: 'طلب الحجز وتأكيده', p: ['إرسال النموذج عبر الموقع هو طلب حجز مبدئي، ولا يُنشئ التزامًا نهائيًا على الشركة بتوفير المقاعد أو الغرف. يتم الحجز عند توفر المقاعد، وتواصل فريق الشركة معك لتأكيد البيانات والتفاصيل، وسدادك للمبلغ أو الدفعة المتفق عليها، ثم إخطارك بتأكيد الحجز.', 'يظهر رقم الحجز بعد إرسال الطلب لمتابعة حالته من صفحة «تتبع حجزك». وقد نعتذر عن طلب في حال عدم توفر المقاعد أو لوجود خطأ في البيانات.'] },
  { h: 'الأسعار وما يشمله البرنامج', ul: [
    'الأسعار المعروضة بالجنيه المصري للفرد البالغ، وتختلف حسب موعد السفر ونوع الغرفة (ثنائية، ثلاثية، رباعية).',
    'يُحتسب سعر الطفل بنسبة من سعر الفرد حسب ما يوضحه نموذج الحجز، ويؤكده الفريق عند التواصل.',
    'يوضح كل برنامج ما يشمله وما لا يشمله. ما لم يُذكر صراحةً ضمن الشمول فهو على نفقة المسافر، كالمصاريف الشخصية والزيارات الإضافية.',
    'قد تتغير الأسعار قبل التأكيد بسبب تغير تكلفة الطيران أو الخدمات أو سعر الصرف. السعر الذي تُؤكَّد به كتابيًا هو الملزم للطرفين.',
  ] },
  { h: 'الدفع', p: ['يتم الاتفاق على طريقة الدفع وجدوله مع فريق الشركة بعد التواصل معك. لا يتم تحصيل أي مبالغ عبر الموقع حاليًا. ننصح بالسداد عبر القنوات الرسمية التي تعلنها الشركة فقط والحصول على إيصال بكل دفعة، وعدم تحويل أموال لأي جهة تدّعي تمثيل الشركة دون التأكد منها عبر أرقامنا المعلنة.'] },
  { h: 'المستندات والتأشيرات', ul: [
    'على المسافر تجهيز جواز سفر ساري وفق المدة التي تُشترط، والصور والمستندات المطلوبة في المواعيد التي يحددها الفريق.',
    'تخضع التأشيرات والإذن بالسفر لقرار الجهات الرسمية، ولا تضمن الشركة قبول أي طلب.',
    'تتغير اشتراطات الدخول والتطعيمات من وقت لآخر، ونُعلم العميل بما نعلمه منها دون أن يعفيه ذلك من التحقق بنفسه.',
    'قد لا تُسترد الرسوم التي دُفعت فعليًا للجهات الخارجية عند رفض الطلب أو عدم استكمال المستندات (راجع سياسة الإلغاء والاسترداد).',
  ] },
  { h: 'التعديل والإلغاء من جانب العميل', p: ['يحق للعميل طلب تعديل الحجز أو إلغائه وفق سياسة الإلغاء والاسترداد المنشورة، وبحسب الشروط الخاصة بكل برنامج ومرحلة الحجز. يتم الطلب عبر الهاتف أو واتساب أو بزيارة المكتب مع ذكر رقم الحجز، ولا يُعتد بالطلب إلا بعد تأكيد الشركة استلامه.'] },
  { h: 'التغيير أو الإلغاء من جانب الشركة', p: ['قد تضطر الشركة لتعديل بعض تفاصيل البرنامج لأسباب خارجة عن إرادتها، مثل تغيير مواعيد الطيران أو استبدال فندق بآخر من نفس المستوى أو أعلى، أو تعديل ترتيب الزيارات. نبذل جهدنا لإخطارك في أقرب وقت وتقديم بديل مناسب.', 'وإن اضطرت الشركة لإلغاء برنامج أو موعد (كعدم اكتمال العدد أو لقرار رسمي) فللعميل الخيار بين استرداد ما دفعه كاملًا أو الانتقال إلى موعد أو برنامج بديل.'] },
  { h: 'التزامات المسافر وسلوكه', ul: [
    'الالتزام بمواعيد الرحلات والتجمعات وتعليمات المشرف والجهات الرسمية وأنظمة المملكة والأماكن المقدسة.',
    'المحافظة على وثائقه وممتلكاته، وتحمل مسؤولية فقدها أو إتلافها.',
    'عدم الإضرار بباقي أفراد المجموعة، وللشركة اتخاذ ما يلزم حيال أي تصرف يعرّض الرحلة أو غيره للخطر.',
  ] },
  { h: 'الحالة الصحية والتأمين', p: ['يتحمل المسافر مسؤولية التأكد من لياقته الصحية للسفر وأداء المناسك، وإخطار الشركة مسبقًا بأي حالة خاصة (كبار السن، الأمراض المزمنة، الحمل، احتياجات الحركة) لنساعده في الترتيب. ننصح بالحصول على تأمين سفر وصحي مناسب.'] },
  { h: 'القوة القاهرة', p: ['لا تتحمل الشركة مسؤولية التأخير أو عدم تنفيذ أي جزء من البرنامج إذا نتج عن ظروف خارجة عن إرادتها، كالكوارث الطبيعية والأوبئة والحروب وإغلاق المجال الجوي أو الحدود والقرارات الرسمية وتعطل أنظمة الغير. وتعمل في مثل هذه الحالات على توفير بدائل مناسبة أو معالجة المبالغ وفق ما تسمح به الظروف والتزامات الجهات المتعاقدة.'] },
  { h: 'حدود المسؤولية', p: ['تؤدي الشركة خدماتها بعناية الشخص المعتاد. ولا تتحمل مسؤولية الأضرار غير المباشرة، ولا مسؤولية عما يقع بفعل المسافر أو أطراف ثالثة لا تتحكم بها، ولا عن الأضرار الناتجة عن مخالفة المسافر للتعليمات. ولا يخل ذلك بحقوق العميل المقررة بنص قانوني لا يجوز الاتفاق على خلافه.'] },
  { h: 'الاستخدام المقبول للموقع', ul: [
    'يُمنع استخدام الموقع في أي نشاط مخالف للقانون أو تقديم بيانات كاذبة أو منتحلة.',
    'يُمنع محاولة اختراق الموقع أو تعطيله أو الإفراط في إرسال الطلبات الآلية أو جمع بياناته آليًا دون إذن.',
    'يحق للشركة إيقاف الوصول أو تجاهل الطلبات التي يُشتبه في إساءة استخدامها.',
  ] },
  { h: 'الملكية الفكرية', p: ['اسم «مكة للسياحة» وشعارها وتصاميم الموقع ونصوصه ورسوماته ومقالاته مملوكة للشركة أو مرخصة لها، ولا يجوز نسخها أو إعادة نشرها أو استخدامها تجاريًا دون إذن كتابي. يمكنك اقتباس مقاطع قصيرة مع الإشارة للمصدر.'] },
  { h: 'الشكاوى وتسوية الخلافات', p: ['نرحب بملاحظاتك وشكاواك. تواصل معنا أولًا على الأرقام المعلنة وسنسعى لحل الأمر ودّيًا في أقرب وقت. ننصح بتقديم الشكوى كتابيًا (واتساب أو بالمكتب) وذكر رقم الحجز والتفاصيل.'] },
  { h: 'القانون الواجب التطبيق', p: ['تخضع هذه الشروط وتُفسَّر وفق القوانين المعمول بها في جمهورية مصر العربية، وتختص المحاكم المصرية بالنظر في أي نزاع لم يُسَوَّ ودّيًا، دون الإخلال بحق المستهلك في اللجوء للجهات المختصة بحماية المستهلك.'] },
  { h: 'التعديلات والتواصل', p: [`قد نعدّل هذه الشروط من وقت لآخر، وتسري التعديلات من تاريخ نشرها. أما الحجوزات المؤكدة قبل التعديل فتبقى خاضعة للشروط وقت تأكيدها. للتواصل: ${site.value.name}، ${site.value.address}، هاتف ${phoneDisplay.value}.`] },
])
</script>
<template><LegalPage eyebrow="قانوني" title="الشروط والأحكام" intro="قواعد واضحة تحمي حقك وحقنا، من أول طلب حجز إلى العودة بالسلامة." updated="9 أكتوبر 2026" :highlights="highlights" :sections="sections" /></template>
